"""Report builder for ledger-worker (owner: Bartek)."""
import re
import json


def build_report(records):
    out = []
    for r in records:
        out.append({"id": r["id"], "total": r["total"]})
    return out


def to_json(records):
    return json.dumps(build_report(records), indent=2)

